import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二百零八章 不被毒瘤恼害","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/208第二百零八章 不被毒瘤恼害.md","filePath":"meditation/巴利文大藏经/208第二百零八章 不被毒瘤恼害.md"}'),r={name:"meditation/巴利文大藏经/208第二百零八章 不被毒瘤恼害.md"};function _(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第二百零八章-不被毒瘤恼害" tabindex="-1">第二百零八章 不被毒瘤恼害 <a class="header-anchor" href="#第二百零八章-不被毒瘤恼害" aria-label="Permalink to &quot;第二百零八章 不被毒瘤恼害&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部20相应11经/狐狼经(譬喻相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“弟子们，你们晚上曾经听到过狼的嚎叫声吗？”</p><p>出家弟子们回答：“世尊，我们晚上听到过狼的嚎叫。”</p><p>佛陀说：“弟子们，有一只狼，它身上长满了毒瘤、毒疮，但是它仍然随意自在的到处走动，它仍然随意自在的到处站立，它仍然随意自在的到处坐下，它仍然随意自在的到处躺卧，冷风狂吹到它的身体上，它也不为所动。</p><p>弟子们，对于那些自称是如来弟子的修行人，他们如果能够像这只狼一样，能够不被自己身上的毒瘤、毒疮障碍、烦恼就好了。</p><p>弟子们，因此，你们应该这样去修行：「我们不要被一切的烦恼和痛苦束缚捆绑，我们不要被一切的烦恼和痛苦障碍、困扰，我们要管束好自己的行为、言语、念想，我们要不放逸自己的行为做恶事。我们不要身体行为做恶事，我们不要口说恶言，我们不要内心生起恶念，我们要身体行为做善事，口说善言，内心生起善念，我们不要胡思乱想，我们不要胡作非为。我们要精进的按世尊的正法去修行，我们要将内心安住在清净的境界之中。」弟子们，你们就应该这样去修行。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',9)]))}const f=e(r,[["render",_]]);export{m as __pageData,f as default};
